  "text:The cat is on a mat.": "/audio/55f5c7523e1f6c4acb2e8cb1.mp3",
  "text:A rat is on the mat too.": "/audio/5edf38744047cc04d2e82ddb.mp3",
  "text:The cat and the rat run.": "/audio/09a8e8a35f712a1b9a8c86bf.mp3",
  "text:I see a map.": "/audio/88487033e0031e30b4bca9d0.mp3",
  "text:The map is on a mat.": "/audio/17a41aa7e4fc99d056ff4ce8.mp3",
  "text:The mat is by a tap.": "/audio/caa2dc22961925a631949322.mp3",
  "text:The tap is not on.": "/audio/fb805b1c1169c5554b3ee7ba.mp3",
  "word:map": "/audio/bdb67322f747478909f778ed.mp3",
  "word:by": "/audio/979019318a974adae2843cd1.mp3",
  "text:Dad has a hat.": "/audio/e0d620ba5ac7753d17f8191d.mp3",
  "text:Dad is at the bus stop.": "/audio/b6ba74ae7c26a87e7d6ca4b6.mp3",
  "text:The bus is red.": "/audio/54c708ff18bbfc08d6984c9c.mp3",
  "text:Dad can get on the bus.": "/audio/c1603ec6427a1fa64f8538e6.mp3",
  "word:Dad": "/audio/c2c3efd6f17917580363d001.mp3",
  "word:bus": "/audio/3c814f17fa7c79106d4ffa0e.mp3",
  "word:stop": "/audio/2c12aff563464b6a86e55f84.mp3",
  "word:get": "/audio/52e62e3851bc261fa5977296.mp3",
  "text:I see a fish shop.": "/audio/7d058934e8212ae6c19ff65b.mp3",
  "text:The fish is in a big tank.": "/audio/922331485fbe2750d83e953b.mp3",
  "text:A man has a bag.": "/audio/1621b04049668ac35f0c249d.mp3",
  "text:He can get a fish for his tank.": "/audio/5dbe376ec65a115c16c8f6d0.mp3",
  "word:big": "/audio/f02c08ee37ea0d793b2acc73.mp3",
  "word:tank": "/audio/62c93eb375643d66877ee28d.mp3",
  "word:man": "/audio/53f3a5acf4d795da7280a730.mp3",
  "text:A ship is at the dock.": "/audio/3c81b1dea1c0504480f932ea.mp3",
  "text:A fish is by the ship.": "/audio/1a850484f9b3efc2bacc211d.mp3",
  "text:The ship is big.": "/audio/1891b30e5304589e4da5aaad.mp3",
  "text:The ship can go.": "/audio/d4cde97e85ab4503ada59600.mp3",
  "word:dock": "/audio/5c7694116ef0fcc294d30337.mp3",
  "word:go": "/audio/a90f0013e07c135a41cafb85.mp3",
  "text:I see a shell.": "/audio/ffbe468d8a61fbc4391d82ca.mp3",
  "text:The shell is in my hand.": "/audio/9845ba60c8c372e5743c753e.mp3",
  "text:I put it in a bag.": "/audio/7b277843f52554c71f631d5a.mp3",
  "text:The shell is for Dad.": "/audio/c47d8b5e0972b176a809b013.mp3",
  "word:hand": "/audio/45e9298223539374f71bb695.mp3",
  "word:put": "/audio/64b802388b3fc608b0c68f48.mp3",
  "text:The cat ran to the shed.": "/audio/16c87b96309fd847b2ab738a.mp3",
  "text:It sat in the shed.": "/audio/1ed3f6e3de82c92af547fb1c.mp3",
  "text:The sun is hot.": "/audio/50951ad8d921d92ff409b61b.mp3",
  "text:The cat can nap in the shed.": "/audio/12f328db675cc8e441e7e255.mp3",
  "word:ran": "/audio/c1e3dd8f830990582988bd2a.mp3",
  "word:shed": "/audio/0a275a698c9b551db2418cd9.mp3",
  "word:hot": "/audio/7c7ab36a6bcbe5137a895b2c.mp3",
  "text:A chip is on my dish.": "/audio/b95939d90fd07b16fc3136a9.mp3",
  "text:Fish is on the dish too.": "/audio/3b30dc4ca46abc2f8f90955b.mp3",
  "text:The dish is hot.": "/audio/5b4eb45d5db2f1d69beae5cd.mp3",
  "text:I sit with Dad.": "/audio/231a00049dc536f43b214aa8.mp3",
  "word:dish": "/audio/288cae283932ac27032b7c1e.mp3",
  "text:Dad has a spot on his chin.": "/audio/acb86b5ecb272cbdae7261e8.mp3",
  "text:I tap my chin too.": "/audio/0f8432ffc45a7a6234645c75.mp3",
  "text:We can chat.": "/audio/fbb12be90899d045c000704b.mp3",
  "text:Dad and I sit on a mat.": "/audio/a337f272d43b530f554e6b5f.mp3",
  "word:spot": "/audio/b1d3ac8550f3004cffd1d7ab.mp3",
  "text:A chick is with the hen.": "/audio/3f9e484700abefb2ad63c204.mp3",
  "text:The chick can run.": "/audio/2ec9f511e3e55cc8a30a0c31.mp3",
  "text:The hen can run too.": "/audio/4a4769a2717ab1e6ee178b14.mp3",
  "text:They stop in the sun.": "/audio/05cf16397aeb61fd04c271ac.mp3",
  "word:chick": "/audio/dc9c3c4023ff691159f01b7b.mp3",
  "text:We sit on a bench.": "/audio/ccc90d9ff5553ccd9abf7736.mp3",
  "text:The bench is in the sun.": "/audio/96c08d1ea7840a99ac29f0f0.mp3",
  "text:We can chat on the bench.": "/audio/e5f0c17f115021770e7a4a77.mp3",
  "text:Then we get up and run.": "/audio/681e495e02f43a1582013845.mp3",
  "word:bench": "/audio/912a0cf92041883b024a1db4.mp3",
  "word:Then": "/audio/1a9d495f72f2edd8807adf0e.mp3",
  "text:Rain is on the path.": "/audio/0b7b2e41633ae601f667fdf7.mp3",
  "text:A snail is on the path.": "/audio/867f2bf281a35d7744bbe273.mp3",
  "text:I wait for the rain to stop.": "/audio/31b9e56e5660fc645a897b46.mp3",
  "text:Then I see the snail.": "/audio/fdb253885b8494866ac227d1.mp3",
  "word:path": "/audio/228cb8f97e6e5e53ffbf5ff7.mp3",
  "word:wait": "/audio/4e8fe96405c40cd961e03a5a.mp3",
  "word:then": "/audio/dff8e25d6d40a19d8503cc64.mp3",
  "text:We wait for the train.": "/audio/d1dfce9c9ca302fde1f52390.mp3",
  "text:The train is red.": "/audio/3b23915986a0e1b07abd3a4d.mp3",
  "text:I have a bag on my lap.": "/audio/1639ca3bb8851b3c6f8e7cc0.mp3",
